        }
        const projectName = activeProjectSegment()
        if (projectName) {
          return { name: 'home', params: { projectName }, replace: true }
        }
        // No active project yet: the root bootstrap loads one and the next
        // guard pass scopes the URL to it.
        return true
      }

      // The company shell is project-independent: never let the guard scope it
      // to the active project (companies orchestrate projects, not the other
      // way around).
      if (to.name === 'company-home') {
        return true
      }

      // ── Browser session route → keep the store selection in sync ──
      // "/:projectName/browsers/:sessionId" renders the browser-sessions screen,
      // which shows the session panel (live browser + docked chat) only for the
      // SELECTED session. The selection lives in the store, so a deep link or a
      // refresh on that URL must restore it from the route param.
      if ((to.name === 'browser-session' || to.name === 'computer-session') && to.params.sessionId) {
        const sessionId = String(to.params.sessionId)
        if ($storex.browsers.selectedSessionId !== sessionId) {
          $storex.browsers.selectSession(sessionId)
        }
      }

      // ── Any other named route renders as-is ──────────────────────
      // Single mode (every route except ".../desktop") shows one app at a
      // time; desktop mode is the dockview workspace. The active route is the
      // single source of truth for which mode we are in (see isDesktopMode
      // above), so there is nothing left to redirect here.
      return true
    },

    // ════════════════════════════════════════════════════════════════
    // UNIFIED APP OPEN (exposed to the UI store & components)
    // ════════════════════════════════════════════════════════════════

    openApp,

    // ════════════════════════════════════════════════════════════════
    // CHAT NAVIGATION
    // ════════════════════════════════════════════════════════════════

    chats: {
      list() {
        $router.push(routes.chat.list())
      },

      open(chatId, chatName) {
        if (!chatId) {
          console.warn('[Navigation] chats.open: invalid chatId', chatId)
          return
        }

        const name = chatName || `chat-${chatId}`
        openApp('chat', {
          chat: {
            id: chatId,
            name,
            owner_project_id: $navigation.activeProject?.project_id
          }
        })
      },

      openWithWorkspace(chatId, chatName, workspaceId, workspaceName) {
        if (!chatId || !workspaceId) {
          console.warn('[Navigation] chats.openWithWorkspace: invalid chat or workspace', { chatId, workspaceId })
          return
        }

        openApp('chat', {
          chat: {
            id: chatId,
            name: chatName || `chat-${chatId}`,
            owner_project_id: $navigation.activeProject?.project_id
          },
          workspace: {
            id: workspaceId,
            name: workspaceName || `workspace-${workspaceId}`
          }
        })
      }
    },

    // ════════════════════════════════════════════════════════════════
    // TEAM NAVIGATION
    // ════════════════════════════════════════════════════════════════

    teams: {
      // Open the team view (last selected / first team)
      list() {
        openApp('team')
      },

      // Open the team view focused on a specific team
      open(teamId) {
        if (!teamId) {
          console.warn('[Navigation] teams.open: invalid teamId', teamId)
          return
        }
        openApp('team', { teamId })
      }
    },

    companies: {
      // Open the company dashboard (last selected / first company). Company
      // mode uses the project-independent "/company" shell.
      list() {
        if ($storex.users?.isCompanyMode) {
          const companyId = $storex.users.primaryCompanyId
          $router.push({ name: 'company-home', params: companyId ? { companyId } : {} })
          return
        }
        openApp('company')
      },

      // Open a specific company
      open(companyId) {
        if (!companyId) {
          console.warn('[Navigation] companies.open: invalid companyId', companyId)
          return
        }
        if ($storex.users?.isCompanyMode) {
          $router.push({ name: 'company-home', params: { companyId } })
          return
        }
        openApp('company', { companyId })
      }
    },

    // ════════════════════════════════════════════════════════════════
    // MEET NAVIGATION
    // ════════════════════════════════════════════════════════════════

    meets: {
      list() {
        openApp('meet', {})
      },

      open(meetId) {
        if (!meetId) {
          console.warn('[Navigation] meets.open: invalid meetId', meetId)
          return
        }
        openApp('meet', { meetId })
      }
    },

    // ════════════════════════════════════════════════════════════════
    // WORKSPACE NAVIGATION
    // ════════════════════════════════════════════════════════════════

    workspaces: {
      list() {
        openApp('workspaces')
      },

      open(workspaceOrId, workspaceName) {
        // Accept either a full workspace object (preferred: it carries name,
        // path and any other metadata) or a legacy (id, name) pair.
        const workspace = (workspaceOrId && typeof workspaceOrId === 'object')
          ? workspaceOrId
          : { key: workspaceOrId, name: workspaceName }

        if (!workspace?.key) {
          console.warn('[Navigation] workspaces.open: invalid workspace', workspaceOrId)
          return
        }

        const name = workspace.name || `workspace-${workspace.key}`

        // Check if currently in chat view
        if ($navigation.isChatView) {
          const chatId = $navigation.getChatId()
          const chatName = $navigation.getChatName()

          if (chatId) {
            $navigation.chats.openWithWorkspace(chatId, chatName, workspace.key, name)
            return
          }
        }

        // Forward the whole workspace under the `workspace` key (same
        // convention as `chat`) so name/path reach the panel params.
        openApp('workspace', { workspace })
      }
    },

    // ════════════════════════════════════════════════════════════════
    // BROWSER NAVIGATION
    // ════════════════════════════════════════════════════════════════

    browsers: {
      list() {
        openApp('browser-sessions')
      },

      // Open a session in the browser-sessions workspace.
      //
      // That screen is the ONLY place a live browser is docked: its panel owns
      // the [ live browser | session chat ] splitter (see
      // components/browsers/BrowserSessionPanel.vue). Opening a separate
      // 'browser-viewer' panel instead produced a second, chat-less browser —
      // the session chat stayed behind in the sessions panel or, worse, was
      // opened as its own panel outside the splitter. Selecting the session and
      // showing the workspace keeps browser and chat in the same split.
      open(sessionId, sessionName) {
        if (!sessionId) {
          console.warn('[Navigation] browsers.open: invalid sessionId', sessionId)
          return
        }

        $storex.browsers.selectSession(sessionId)
        openApp('browser-sessions', { name: sessionName || undefined })
      }
    },

    // ════════════════════════════════════════════════════════════════
    // PRIMARY APP NAVIGATION
    // ════════════════════════════════════════════════════════════════

    apps: {
      // Generic entry point – used by the UI store (setActiveTab, openers…)
      openApp,

      openHome() {
        $router.push(routes.home.open())
      },

      // Composer screen (mobile / single mode). Desktop mode keeps opening a
      // quick-chat panel through service.chat.newQuickChat().
      openNewChat() {
        $router.push({ name: 'new-chat' })
      },

      openDesktop() {
        $router.push(routes.desktop.open())
      },

      openMessenger() {
        openApp('messenger')
      },

      openMeet(meetId) {
        openApp('meet', { meetId })
      },

      openKanban() {
        openApp('tasks')
      },

      // Open the Task Manager directly on the Planning view
      openPlanning() {
        openApp('planning')
      },

      openFileExplorer() {
        openApp('file-explorer')
      },

      // Git repository view, rendered by components/repo/GitView.vue
      // (see router/index.ts → "/:projectName/git-view")
      openGitView() {
        openApp('git-view')
      },

      // Docker infrastructure, rendered by views/infra/InfraView.vue
      // (see router/index.ts → "/:projectName/infra")
      openInfra() {
        openApp('infra')
      },

      openWiki() {
        openApp('wiki')
      },

      // Open the team view. An optional team id opens that specific team
      // ("/:projectName/team/:teamId"); without it the last team is shown.
      openTeam(teamId) {
        openApp('team', teamId ? { teamId } : {})
      },

      openViews() {
        console.warn('[Navigation] openViews: no Views route yet')
      },

      openKnowledge() {
        openApp('knowledge')
      },

      openAnalytics() {
        openApp('analytics')
      }
    },

    // ════════════════════════════════════════════════════════════════
    // WORKSPACE CONTEXT (for reading current state)
    // ════════════════════════════════════════════════════════════════

    workspace: {
      getCurrentWorkspace() {
        const workspaceId = $navigation.getWorkspaceId()
        const workspaceName = $navigation.getWorkspaceName()

        if (workspaceId) {
          return { id: workspaceId, name: workspaceName }
        }
        return null
      },

      hasContext() {
        return $navigation.hasWorkspaceContext
      }
    },

    // ════════════════════════════════════════════════════════════════
    // SESSION CONTEXT (for reading current state)
    // ════════════════════════════════════════════════════════════════

    session: {
      getCurrentSession() {
        const sessionId = $navigation.getSessionId()
        const sessionName = $navigation.getSessionName()

        if (sessionId) {
          return { id: sessionId, name: sessionName }
        }
        return null
      },

      hasContext() {
        return $navigation.hasSessionContext
      }
    }
  }

  return $navigation
}

